const DEBUG_MAX_EVENTS=300;
let debugEvents=[],debugFps=0,debugFrames=0,debugLastFpsAt=performance.now(),debugBuildReport=null,debugOverlayEnabled=false;
function debugSafe(value,depth=0){
 if(depth>3)return "[depth]";
 if(value==null||typeof value==="string"||typeof value==="number"||typeof value==="boolean")return value;
 if(value instanceof Error)return {name:value.name,message:value.message,stack:value.stack||""};
 if(Array.isArray(value))return value.slice(0,20).map(v=>debugSafe(v,depth+1));
 if(typeof value==="object"){
  const out={};let n=0;
  for(const [k,v] of Object.entries(value)){
   if(++n>30){out.__truncated=true;break}
   try{out[k]=debugSafe(v,depth+1)}catch{out[k]="[unavailable]"}
  }
  return out;
 }
 return String(value);
}
function debugLog(type,data={}){
 debugEvents.push({at:new Date().toISOString(),ms:Math.round(performance.now()),type,data:debugSafe(data)});
 if(debugEvents.length>DEBUG_MAX_EVENTS)debugEvents.splice(0,debugEvents.length-DEBUG_MAX_EVENTS);
 try{if(window.__DBE_UI_READY&&typeof renderDebug==="function")renderDebug(false)}catch{}
}

