function profileFor(id){
 id=Math.round(clamp(id,1,PROFILE_COUNT));
 const d=PITCH_IDENTITIES[id-1];
 return {
  ...d,
  family:{name:d.category},
  motion:{name:d.style,key:d.style.toLowerCase()},
  color:hsv((id*.61803398875)%1,.84,1),
  signature:`${d.category} • ${d.theme} • ${d.style}`
 };
}

