function variantFor(id){return VARIANTS[Math.round(clamp(id,1,VARIANT_COUNT))-1]}
function variantFeel(id){
 return ({
  1:"Pure base pitch. No transformation.",
  2:"Rush: fast and almost straight with only a tiny late twitch.",
  3:"Heavy: slow, weighty, and falls hard through the final third.",
  4:"Dirty: two-stage break — early one direction, late violently the other.",
  5:"Backdoor: begins clearly outside and sweeps back across the zone.",
  6:"Float: extremely slow with a huge balloon arc.",
  7:"Turbo: near-laser speed, nearly straight, tiny late lift.",
  8:"Late Snap: straight for most of the flight, then a violent diagonal snap.",
  9:"Early Break: huge movement immediately, then it straightens.",
  10:"Reverse: inverts the base pitch's movement pattern.",
  11:"Sinker Bias: turns almost anything into a hard downward finisher.",
  12:"Riser Bias: turns almost anything into an obvious rising finisher.",
  13:"Sidewinder: giant horizontal S-curve.",
  14:"Corkscrew: visible circular/orbiting flight.",
  15:"Phantom: drift → reversal → second late cut.",
  16:"Chaos+: multi-axis, multi-frequency, multi-stage break."
 })[Number(id)]||"";
}
function challengeFor(index){
 index=Math.round(clamp(index,1,CHALLENGE_COUNT));
 return {index,profileId:Math.floor((index-1)/VARIANT_COUNT)+1,variantId:((index-1)%VARIANT_COUNT)+1};
}
function challengeIndex(profileId,variantId){
 return (Math.round(clamp(profileId,1,PROFILE_COUNT))-1)*VARIANT_COUNT+Math.round(clamp(variantId,1,VARIANT_COUNT));
}
function variantColor(p,v){
 const hue=((v.id-1)/VARIANT_COUNT + (p.id%41)/41*.038)%1;
 const sat=v.id===6?.60:v.id===7?.98:v.id===16?.97:.90;
 const val=v.id===3?.84:v.id===15?.91:1;
 return hsv(hue,sat,val);
}


