addEventListener("error",e=>debugLog("window.error",{message:e.message,file:e.filename,line:e.lineno,column:e.colno,error:e.error}));
addEventListener("unhandledrejection",e=>debugLog("unhandledrejection",{reason:e.reason}));

function intensity(){return clamp(finite(config.intensity,1),.70,1.28)}
function late(t,start=.6){return clamp((t-start)/(1-start),0,1)}

function primitiveMotion(key,p,t,reach,secondary=false){
 const shape=((key%25)+25)%25,band=Math.floor(key/25);
 const bandDir=(band%2)?-1:1,bandAmp=1+Math.min(3,band)*.13;
 const d=p.direction*bandDir,a=p.amp*intensity()*(secondary ? .58 : 1)*bandAmp;
 const ph=p.phase+band*.88,f=p.frequency+band*.72;
 const lateStart=band?.69:.56;
 let x=0,y=0;
 switch(shape){
  case 0: x+=d*.18*a*reach*late(t,.75)**2; break; // dart
  case 1: x+=d*.88*a*reach*late(t,lateStart)**2; break; // late cut
  case 2: x+=d*1.05*a*reach*Math.sin(Math.PI*t); break; // sweep
  case 3: y+=1.22*a*Math.sin(Math.PI*t)-.72*a*reach*late(t,.56)**2; break; // curve
  case 4: y-=1.00*a*reach*late(t,.52)**2; break; // sink
  case 5: y+=.88*a*reach*late(t,.50)**2; break; // rise
  case 6: x+=d*.78*a*reach*Math.sin(t*Math.PI*2.05+ph*.15); break; // S
  case 7: x+=d*.46*a*reach*Math.sin(t*Math.PI*(8+f)+ph); break; // zig
  case 8: x+=d*.48*a*reach*Math.sin(t*Math.PI*5+ph);y+=.40*a*reach*Math.cos(t*Math.PI*5+ph);break; // orbit
  case 9: x+=d*.34*a*reach*Math.sin(t*Math.PI*(11+f)+ph);y+=.23*a*reach*Math.sin(t*Math.PI*(7+f*.5)+ph*.7);break; // wobble
  case 10: x+=d*.66*a*reach*Math.sin(Math.PI*t)-d*.84*a*reach*late(t,.67)**2; break; // boomerang
  case 11: x+=d*.44*a*reach*Math.sin(t*Math.PI*6+ph);y+=.35*a*reach*Math.cos(t*Math.PI*6+ph); break; // corkscrew
  case 12: y+=.66*a*Math.sin(Math.PI*t)-1.08*a*reach*late(t,.70)**3; break; // deadfall
  case 13: y+=2.10*a*Math.sin(Math.PI*t);x+=d*.18*a*reach*Math.sin(Math.PI*t);break; // float arc
  case 14: x+=d*.62*a*reach*Math.sin(Math.PI*clamp(t/.55,0,1))-d*.90*a*reach*late(t,.60)**2;break; // two-stage
  case 15: x-=d*.86*a*reach*Math.sin(Math.PI*t);y-=.18*a*reach*late(t,.58)**2;break; // reverse
  case 16: x+=d*.08*a*reach*Math.sin(Math.PI*t)+d*.94*a*reach*late(t,.78)**2;break; // tunnel
  case 17: x+=d*.24*a*reach*Math.sin(Math.PI*t)-d*.98*a*reach*late(t,.72)**2;y-=.18*a*reach*late(t,.76)**2;break; // whip
  case 18: x+=d*.64*a*reach*Math.sin(t*Math.PI*3.1+ph*.25);y+=.12*a*reach*Math.sin(t*Math.PI*2.15+ph);break; // snake
  case 19: x+=d*.40*a*reach*Math.sin(t*Math.PI*4+ph);y+=.28*a*reach*Math.cos(t*Math.PI*4+ph);break; // pulse orbit
  case 20: x+=d*.12*a*reach*Math.sin(Math.PI*t)+d*1.15*a*reach*late(t,.80)**2;break; // portal snap
  case 21: x+=d*.30*a*reach*Math.sin(t*Math.PI*3+ph);y-=.88*a*reach*Math.sin(Math.PI*t)*(.3+.7*t);break; // gravity well
  case 22: x-=d*.70*a*reach*Math.sin(Math.PI*t)+d*1.06*a*reach*late(t,.73)**2;break; // slingshot
  case 23: y+=.42*a*Math.sin(Math.PI*t)-.48*a*reach*late(t,.58)**2+.58*a*reach*late(t,.80)**2;break; // rebound
  case 24: x+=d*.06*a*reach*Math.sin(t*Math.PI*2+ph);y+=.10*a*Math.sin(Math.PI*t);x+=d*1.05*a*reach*late(t,.84)**2;break; // freeze then go
 }
 return{x,y};
}

function legendaryMotion(p,t,reach){
 if(!p.special)return null;
 const d=p.direction,a=p.amp*intensity(),ph=p.phase,f=p.frequency;
 let x=0,y=0;
 switch(p.special){
  case"real_fourseam":x=d*.08*a*reach*Math.sin(Math.PI*t);break;
  case"real_twoseam":x=d*.55*a*reach*Math.sin(Math.PI*t);y=-.24*a*reach*late(t,.56)**2;break;
  case"real_cutter":x=-d*.74*a*reach*late(t,.62)**2;break;
  case"real_sinker":y=-.86*a*reach*late(t,.50)**2;x=d*.18*a*reach*Math.sin(Math.PI*t);break;
  case"real_slider":x=d*.76*a*reach*Math.sin(Math.PI*t)+d*.28*a*reach*late(t,.70)**2;break;
  case"real_sweeper":x=d*1.18*a*reach*Math.sin(Math.PI*t)*(.42+.58*t);break;
  case"real_126":y=1.30*a*Math.sin(Math.PI*t)-.88*a*reach*late(t,.56)**2;break;
  case"real_knucklecurve":x=d*.23*a*reach*Math.sin(t*Math.PI*(10+f)+ph);y=.78*a*Math.sin(Math.PI*t)-.64*a*reach*late(t,.58)**2;break;
  case"real_circle":x=d*.42*a*reach*Math.sin(Math.PI*t);y=.46*a*Math.sin(Math.PI*t)-.20*a*reach*late(t,.65)**2;break;
  case"real_splitter":y=-1.10*a*reach*late(t,.66)**3;break;
  case"real_fork":y=-1.25*a*reach*late(t,.58)**3;break;
  case"real_screw":x=-d*.84*a*reach*Math.sin(Math.PI*t);y=-.30*a*reach*late(t,.55)**2;break;
  case"real_knuckle":x=d*.38*a*reach*Math.sin(t*Math.PI*(11+f)+ph);y=.24*a*reach*Math.cos(t*Math.PI*(8+f*.5)+ph*.7);break;
  case"real_eephus":y=3.80*a*Math.sin(Math.PI*t);break;
  case"real_palm":x=d*.20*a*reach*Math.sin(Math.PI*t);y=.70*a*Math.sin(Math.PI*t)-.26*a*reach*late(t,.66)**2;break;
  case"real_vulcan":x=d*.22*a*reach*Math.sin(Math.PI*t);y=-.92*a*reach*late(t,.62)**2;break;
  case"real_slurve":x=d*.78*a*reach*Math.sin(Math.PI*t);y=.54*a*Math.sin(Math.PI*t)-.50*a*reach*late(t,.56)**2;break;
  case"real_gyro":x=d*.28*a*reach*Math.sin(t*Math.PI*4+ph);y=.18*a*reach*Math.cos(t*Math.PI*4+ph);break;
  case"real_splitchange":x=d*.18*a*reach*Math.sin(Math.PI*t);y=.45*a*Math.sin(Math.PI*t)-.84*a*reach*late(t,.68)**3;break;
  case"real_powercurve":x=d*.22*a*reach*Math.sin(Math.PI*t);y=.90*a*Math.sin(Math.PI*t)-1.05*a*reach*late(t,.53)**2;break;

  case"magic_zoom":
   x=d*.12*a*reach*Math.sin(Math.PI*t)+d*1.22*a*reach*late(t,.72)**2;
   y=.18*a*Math.sin(Math.PI*t)+.82*a*reach*late(t,.74)**2;break;
  case"invisible":
   x=d*.06*a*reach*Math.sin(t*Math.PI*3+ph)+d*.95*a*reach*late(t,.77)**2;
   y=.05*a*Math.sin(Math.PI*t)-.42*a*reach*late(t,.80)**2;break;
  case"black_hole":{
   const r=(1-t)*.82+.12;
   x=d*r*a*reach*Math.sin(t*Math.PI*7+ph);y=r*.72*a*reach*Math.cos(t*Math.PI*7+ph)-.46*a*reach*t*t;break;
  }
  case"gravity_flip":
   y=-.88*a*reach*Math.sin(Math.PI*clamp(t/.55,0,1)) + 1.22*a*reach*late(t,.52)**2;break;
  case"teleport_curve":
   x=d*.22*a*reach*Math.sin(Math.PI*t)+d*1.35*a*reach*late(t,.64)**6;y=.36*a*Math.sin(Math.PI*t);break;
  case"dragon_breath":
   x=d*.92*a*reach*Math.sin(Math.PI*t);y=.26*a*Math.sin(Math.PI*t)-.88*a*reach*late(t,.62)**2;break;
  case"time_freeze":
   y=1.65*a*Math.sin(Math.PI*t);x=d*.10*a*reach*Math.sin(Math.PI*t)+d*.82*a*reach*late(t,.84)**2;break;
  case"lightning":
   x=d*.22*a*reach*Math.sin(t*Math.PI*10+ph)+d*.48*a*reach*late(t,.79)**2;y=.12*a*reach*Math.sin(t*Math.PI*8+ph);break;
  case"rubber_band":
   x=-d*.92*a*reach*Math.sin(Math.PI*t)+d*1.38*a*reach*late(t,.68)**2;break;
  case"ghost_fork":
   x=d*.20*a*reach*Math.sin(t*Math.PI*(10+f)+ph);y=.12*a*reach*Math.cos(t*Math.PI*8+ph)-1.05*a*reach*late(t,.68)**3;break;
  case"orbit_breaker":
   x=d*.72*a*reach*Math.sin(t*Math.PI*5+ph);y=.58*a*reach*Math.cos(t*Math.PI*5+ph)-.72*a*reach*late(t,.76)**2;break;
  case"wrongway":
   x=-d*.70*a*reach*Math.sin(Math.PI*t)+d*.98*a*reach*late(t,.67)**2;break;
  case"magnet":
   x=d*1.22*a*reach*late(t,.48)**2;y=.10*a*Math.sin(Math.PI*t);break;
  case"portal":
   x=-d*.52*a*reach*Math.sin(Math.PI*t)+d*1.18*a*reach*late(t,.70)**5;break;
  case"meteor":
   x=d*.18*a*reach*Math.sin(Math.PI*t);y=-1.45*a*reach*late(t,.46)**2;break;
  case"phoenix":
   y=-.32*a*reach*Math.sin(Math.PI*clamp(t/.42,0,1))+1.18*a*reach*late(t,.48)**2;break;
  case"kraken":
   x=d*1.05*a*reach*Math.sin(t*Math.PI*2.25+ph*.15);y=.16*a*reach*Math.sin(t*Math.PI*4+ph);break;
  case"glitch":
   x=d*.48*a*reach*Math.sin(t*Math.PI*11+ph)+d*.34*a*reach*Math.sin(t*Math.PI*17+ph*.4);y=.18*a*reach*Math.cos(t*Math.PI*13+ph);break;
  case"moon_bounce":
   y=2.35*a*Math.sin(Math.PI*t)+.50*a*reach*late(t,.68)**2;x=d*.16*a*reach*Math.sin(Math.PI*t);break;
  case"prism":
   x=d*.56*a*reach*Math.sin(t*Math.PI*2)-d*.72*a*reach*late(t,.60)**2+d*.82*a*reach*late(t,.82)**2;
   y=.32*a*Math.sin(Math.PI*t);break;
  case"tornado":
   x=d*.58*a*reach*Math.sin(t*Math.PI*8+ph);y=.46*a*reach*Math.cos(t*Math.PI*8+ph);break;
  case"sonic":
   x=d*.04*a*reach*Math.sin(Math.PI*t)+d*.58*a*reach*late(t,.86)**2;y=.05*a*reach*late(t,.88)**2;break;
  case"crystal":
   y=.92*a*Math.sin(Math.PI*t)-.52*a*reach*late(t,.60)**2;x=d*.72*a*reach*late(t,.78)**2;break;
  case"shadow_split":
   x=d*.05*a*reach*Math.sin(Math.PI*t);y=-1.28*a*reach*late(t,.72)**3;break;
  case"quantum_zig":
   x=d*.42*a*reach*Math.sin(t*Math.PI*16+ph)+d*.58*a*reach*late(t,.78)**2;y=.12*a*reach*Math.cos(t*Math.PI*12+ph);break;
  case"vortex_cannon":{
   const grow=.18+.82*t;x=d*.68*a*reach*grow*Math.sin(t*Math.PI*7+ph);y=.52*a*reach*grow*Math.cos(t*Math.PI*7+ph);break;
  }
  case"nightmare":
   x=d*.44*a*reach*Math.sin(t*Math.PI*(12+f)+ph)+d*.20*a*reach*Math.sin(t*Math.PI*19+ph*.3);
   y=.26*a*reach*Math.cos(t*Math.PI*(9+f*.6)+ph*.5);break;
  case"starfall":
   y=1.95*a*Math.sin(Math.PI*t)-1.22*a*reach*late(t,.65)**2;x=d*.14*a*reach*Math.sin(Math.PI*t);break;
  case"hologram":
   x=d*.58*a*reach*Math.sin(t*Math.PI*2.3+ph)-d*.88*a*reach*late(t,.73)**2;y=.18*a*reach*Math.sin(t*Math.PI*5+ph);break;
  case"chaos_comet":
   x=d*.42*a*reach*Math.sin(t*Math.PI*9+ph)+d*.26*a*reach*Math.sin(t*Math.PI*15+ph*.7)-d*.70*a*reach*late(t,.73)**2;
   y=.30*a*reach*Math.cos(t*Math.PI*7+ph)-.90*a*reach*late(t,.68)**2;break;
  default:return null;
 }
 return{x,y};
}

function primaryMotion(p,t,reach){
 const special=legendaryMotion(p,t,reach);
 return special||primitiveMotion(p.aKey,p,t,reach,false);
}

function secondaryMotion(p,t,reach){
 if(p.special)return{x:0,y:0};
 return primitiveMotion(p.bKey,p,t,reach,true);
}


window.DBE_PROFILE_OFFSET=function(progress){
 if(!activeProfile||config.pitchSystem==="vanilla")return null;
 const p=activeProfile,v=activeVariant||variantFor(1);
 const t=clamp(progress,0,1),reach=.16+.84*clamp((.988-t)/.23,0,1);
 const baseA=primaryMotion(p,t,reach),baseB=secondaryMotion(p,t,reach);
 const bx=baseA.x+baseB.x,by=baseA.y+baseB.y,d=p.direction,a=p.amp*intensity(),ph=p.phase;
 let x=bx,y=by;
 switch(v.id){
  case 1: break; // STANDARD
  case 2: x=bx*.22+d*.18*a*reach*late(t,.82)**2; y=by*.20-.06*a*reach*late(t,.86)**2; break; // RUSH
  case 3: x=bx*.70; y=by*.62-1.10*a*reach*late(t,.58)**2-.28*a*Math.sin(Math.PI*t); break; // HEAVY
  case 4:
   x=bx*.35+d*.74*a*reach*Math.sin(Math.PI*clamp(t/.58,0,1))-d*1.12*a*reach*late(t,.60)**2;
   y=by*.42+.20*a*Math.sin(Math.PI*t)-.52*a*reach*late(t,.68)**2; break; // DIRTY
  case 5: x=-d*(.88*a*reach*(1-t))+d*1.28*a*reach*late(t,.50)**2+bx*.22; y=by*.48; break; // BACKDOOR
  case 6: x=bx*.24+d*.34*a*reach*Math.sin(Math.PI*t); y=2.75*a*Math.sin(Math.PI*t)+by*.18-.18*a*reach*late(t,.84)**2; break; // FLOAT
  case 7: x=bx*.08+d*.055*a*reach*Math.sin(t*Math.PI*5+ph); y=by*.06+.20*a*reach*late(t,.76)**2; break; // TURBO
  case 8: x=bx*.05+d*1.34*a*reach*late(t,.76)**2; y=by*.05-.82*a*reach*late(t,.78)**2; break; // LATE SNAP
  case 9:{
   const early=Math.sin(Math.PI*clamp(t/.48,0,1))*(1-clamp((t-.42)/.34,0,1));
   x=bx*.18+d*1.18*a*reach*early; y=by*.20+.44*a*reach*early; break; // EARLY BREAK
  }
  case 10: x=-bx*1.12; y=-by*.94; break; // REVERSE
  case 11: x=bx*.54; y=by*.30-1.42*a*reach*late(t,.54)**2; break; // SINKER BIAS
  case 12: x=bx*.50; y=by*.25+1.22*a*reach*late(t,.50)**2+.30*a*Math.sin(Math.PI*t); break; // RISER BIAS
  case 13: x=d*1.22*a*reach*Math.sin(t*Math.PI*2.15+ph*.12)+bx*.18; y=by*.18-.10*a*reach*late(t,.72)**2; break; // SIDEWINDER
  case 14:{
   const corkAmp=(.32+.68*t)*a*reach;
   x=bx*.18+d*.78*corkAmp*Math.sin(t*Math.PI*6+ph); y=by*.16+.64*corkAmp*Math.cos(t*Math.PI*6+ph); break; // CORKSCREW
  }
  case 15:
   x=bx*.16+d*.62*a*reach*Math.sin(t*Math.PI*1.7+ph*.18)-d*.82*a*reach*late(t,.55)**2+d*.94*a*reach*late(t,.80)**2;
   y=by*.18+.28*a*reach*Math.sin(t*Math.PI*3.2+ph*.4)-.38*a*reach*late(t,.76)**2; break; // PHANTOM
  case 16:
   x=bx*.12+d*.54*a*reach*Math.sin(t*Math.PI*7+ph)+d*.32*a*reach*Math.sin(t*Math.PI*13+ph*.7)-d*.82*a*reach*late(t,.72)**2;
   y=by*.12+.44*a*reach*Math.cos(t*Math.PI*6+ph*.5)+.24*a*reach*Math.sin(t*Math.PI*11+ph)-.72*a*reach*late(t,.68)**2; break; // CHAOS+
 }
 return{x,y};
};
window.DBE_PROFILE_TRAIL=function(){
 const v=activeVariant||variantFor(1),p=activeProfile;
 if(!p)return false;
 const specialTrail=["black_hole","magic_zoom","lightning","orbit_breaker","glitch","tornado","quantum_zig","vortex_cannon","nightmare","chaos_comet"].includes(p.special);
 const styleTrail=["Knuckle","Spiral","Orbit","Chaos","Wave","Snake","Pulse","Ghost"].some(k=>String(p.style).includes(k));
 return !!(v.trail||specialTrail||styleTrail||p.aKey%7===0||p.bKey%11===0);
};
window.DBE_CONTACT_RULE=function(){
 if(!activeProfile||config.pitchSystem==="vanilla")return{center:0,window:1};
 const v=activeVariant||variantFor(1);
 return{center:clamp(activeProfile.center+v.center,-.30,.34),window:clamp(activeProfile.window*v.window,.48,1.22)};
};
window.DBE_PITCH_BASE_SPEED=function(_engineId,original){
 if(!activeProfile||config.pitchSystem==="vanilla")return original;
 const v=activeVariant||variantFor(1);
 return clamp(activeProfile.speed*v.speed,7,72);
};
window.DBE_PITCH_SPEED_MULT=function(){return activeProfile?(.90+.10*intensity()):1};
window.DBE_PITCH_HIT_POWER=function(){
 if(!activeProfile)return null;
 const v=activeVariant||variantFor(1);
 const modifier=v.id===3?1.06:v.id===7?1.05:v.id===6?.94:v.id===16?1.08:1;
 return activeProfile.hitPower*modifier;
};
window.DBE_PITCH_COLOR=function(){
 if(activeProfile?.special==="invisible")return "rgba(20,24,28,.12)";
 return activeProfile?variantColor(activeProfile,activeVariant||variantFor(1)):"#ff3434";
};
window.DBE_PITCH_HAT_COLOR=function(){return config.hatColors&&activeProfile?variantColor(activeProfile,activeVariant||variantFor(1)):null};
window.DBE_PITCH_ANIM_BASE=function(engineId){return Number(engineId)};
window.DBE_PICK_PITCH=function(_count,original){return Number(original)};

function chooseSelection(){
 if(config.pitchSystem==="vanilla")return{profileId:0,variantId:1,challengeId:0};
 if(config.pitchSystem==="manual"){
  const profileId=Math.round(clamp(config.manualPitch,1,PROFILE_COUNT));
  const variantId=Math.round(clamp(config.manualVariant,1,VARIANT_COUNT));
  return{profileId,variantId,challengeId:challengeIndex(profileId,variantId)};
 }
 if(config.pitchSystem==="gauntlet"){
  const c=challengeFor(config.gauntletCurrent);
  return{profileId:c.profileId,variantId:c.variantId,challengeId:c.index};
 }
 if(config.pitchSystem==="legendary"){
  const profileId=1+Math.floor(Math.random()*50),variantId=1+Math.floor(Math.random()*VARIANT_COUNT);
  return{profileId,variantId,challengeId:challengeIndex(profileId,variantId)};
 }
 if(config.pitchSystem==="mystery"){
  const profileId=1+Math.floor(Math.random()*PROFILE_COUNT),variantId=1+Math.floor(Math.random()*VARIANT_COUNT);
  return{profileId,variantId,challengeId:challengeIndex(profileId,variantId)};
 }
 if(config.pitchSystem==="bossladder"){
  const profileId=Math.round(clamp(bossLadder.current,1,50));
  const variantId=1+((profileId*7-1)%VARIANT_COUNT);
  return{profileId,variantId,challengeId:challengeIndex(profileId,variantId)};
 }
 if(Math.random()>clamp(config.frequency,0,1))return{profileId:0,variantId:1,challengeId:0};
 const profileId=1+Math.floor(Math.random()*PROFILE_COUNT);
 const variantId=config.randomVariants?1+Math.floor(Math.random()*VARIANT_COUNT):1;
 return{profileId,variantId,challengeId:challengeIndex(profileId,variantId)};
}
window.DBE_PREPARE_PITCH=function(pitcher){
 if(!pitcher||!Array.isArray(pitcher.V)||!pitcher.V.length)return null;
 if(pitcher.__dbeLockedPitch!=null){
  if(pitcher.Ca){pitcher.Ca.__dbeIsPitcherHat=true;pitcher.Ca.__dbeHatColor=window.DBE_PITCH_HAT_COLOR()}
  showCue(activeProfile,activeVariant);return Number(pitcher.__dbeLockedPitch);
 }
 const vanilla=Number(pitcher.V[Math.floor(Math.random()*pitcher.V.length)]);
 const sel=chooseSelection();
 activeProfileId=sel.profileId;
 activeVariantId=sel.variantId;
 activeChallengeId=sel.challengeId;
 activeProfile=activeProfileId?profileFor(activeProfileId):null;
 activeVariant=variantFor(activeVariantId);
 window.DBE_ACTIVE_PROFILE_ID=activeProfileId;
 window.DBE_ACTIVE_VARIANT_ID=activeVariantId;
 window.DBE_ACTIVE_CHALLENGE_ID=activeChallengeId;
 window.DBE_DISPLAY_PITCH_COLOR=activeProfile?variantColor(activeProfile,activeVariant):null;
 const base=activeProfile?activeProfile.animBase:vanilla; // ALWAYS 0..5
 pitcher.__dbeLockedPitch=base;pitcher.__dbeQueuedPitch=base;pitcher.__dbeWasQueued=true;
 if(pitcher.Ca){pitcher.Ca.__dbeIsPitcherHat=true;pitcher.Ca.__dbeHatColor=window.DBE_PITCH_HAT_COLOR()}
 showCue(activeProfile,activeVariant);
 return base;
};
window.DBE_RELEASE_PITCH_LOCK=function(pitcher){
 if(!pitcher)return;
 pitcher.__dbeLockedPitch=null;pitcher.__dbeQueuedPitch=null;pitcher.__dbeWasQueued=null;
};

const tintCache=new WeakMap();
window.DBE_TINT_SPRITE=function(source,color){
 if(!source||!color)return source;
 let map=tintCache.get(source);if(!map){map=new Map();tintCache.set(source,map)}
 if(map.has(color))return map.get(color);
 const out=document.createElement("canvas");out.width=Math.max(1,source.width||1);out.height=Math.max(1,source.height||1);
 const c=out.getContext("2d");c.drawImage(source,0,0);c.globalCompositeOperation="source-atop";c.globalAlpha=.92;c.fillStyle=color;c.fillRect(0,0,out.width,out.height);c.globalAlpha=1;c.globalCompositeOperation="source-over";
 map.set(color,out);return out;
};

function trait(batter){
 if(!config.playerTraits||!batter)return{power:1,speed:1,label:"Balanced",signature:"unknown",width:0,height:0};
 const f=batter?.v?.Da;if(!Array.isArray(f)||f.length<5)return{power:1,speed:1,label:"Balanced",signature:"unknown",width:0,height:0};
 const width=Math.max(40,+f[3]||90),height=Math.max(70,+f[4]||140);
 const norm=clamp(((width*height)-12500)/9000,-1,1);
 const signature=`${f[0]||"sheet"}:${f[1]||0}:${f[2]||0}:${width}:${height}`;
 const archetype=norm>.58?"Slugger":norm>.28?"Power":norm<-.58?"Speedster":norm<-.28?"Quick":"Balanced";
 const t={power:1+clamp(norm*.10,-.10,.12),speed:1-clamp(norm*.10,-.10,.12),label:archetype,signature,width,height};
 if(signature!=="unknown"){
  discoveredFoods[signature]={
   signature,width,height,label:archetype,power:Number(t.power.toFixed(3)),speed:Number(t.speed.toFixed(3)),
   seen:(discoveredFoods[signature]?.seen||0)+1
  };
  try{localStorage.setItem("dbe_mod_food_traits_v18",JSON.stringify(discoveredFoods))}catch{}
 }
 return t;
}
window.DBE_RUN_DURATION=function(runner){
 const base=28000/26.8,t=trait(runner);
 return base/clamp(finite(t.speed,1),.88,1.12);
};

window.DBE_ON_CONTACT=function(_engineId,error,win,batter){
 lastTrait=trait(batter);
 resetDefensePlay();
 defensePlay.active=!!config.defenseSystem;
 defensePlay.contactAt=performance.now();
 defensePlay.runnerEta=(28000/26.8)/clamp(finite(lastTrait.speed,1),.88,1.12);
 const n=clamp(Number(error)/Math.max(.001,Number(win)),-1,1),quality=Math.max(0,1-Math.abs(n));
 if(quality>=.98){totals.perfectContacts++;unlock("perfect")}
 try{dispatchEvent(new CustomEvent("dbe-bat-contact",{detail:{profileId:activeProfileId,variantId:activeVariantId,challengeId:activeChallengeId,normalized:n,quality,trait:lastTrait}}))}catch{}
};
window.DBE_BAT_POWER_MULT=function(_engineId,error,win){
 const n=clamp(Number(error)/Math.max(.001,Number(win)),-1,1),quality=1-Math.abs(n);
 return(config.variableContact?(.80+.26*quality)*(.97+Math.random()*.06):1)*(config.playerTraits?lastTrait.power:1);
};
window.DBE_BAT_SPRAY_ANGLE=function(error,win){
 const n=clamp(Number(error)/Math.max(.001,Number(win)),-1,1);
 const angle=clamp(90+n*58+(config.variableContact?(Math.random()-.5)*8:0),22,158);
 const foul=config.foulRules && (angle<43||angle>137);
 window.DBE_FOUL_PENDING=!!foul;
 if(foul){
  try{dispatchEvent(new CustomEvent("dbe-foul-contact",{detail:{angle}}))}catch{}
 }
 return angle;
};
window.DBE_SAFE_FOUL=function(){
 if(!window.DBE_FOUL_PENDING)return false;
 window.DBE_FOUL_PENDING=false;
 foulState.total++;
 if(foulState.strikes<2)foulState.strikes++;
 try{dispatchEvent(new CustomEvent("dbe-foul-resolved",{detail:{strikes:foulState.strikes,total:foulState.total}}))}catch{}
 return true;
};

function resetDefensePlay(){
 defensePlay={active:false,pending:false,out:false,safe:false,reason:"",margin:0,contactAt:0,pickupAt:0,ground:false,throwEta:0,runnerEta:0};
 window.DBE_THROW_FIRST=false;
}
window.DBE_FIELDER_PICKUP=function(info={}){
 if(!config.defenseSystem||!defensePlay.active||defensePlay.pending)return;
 defensePlay.pending=true;defensePlay.pickupAt=performance.now();defensePlay.ground=!!info.ground;
 const elapsed=Math.max(0,defensePlay.pickupAt-defensePlay.contactAt);
 const dx=finite(info.fielderX,0)-finite(info.ballX,0),dz=finite(info.fielderZ,0)-finite(info.ballZ,0);
 const distance=Math.sqrt(dx*dx+dz*dz);
 const arm=info.arm==="strong"?1.12:.96;
 const skill=clamp(finite(config.defenseDifficulty,1),.75,1.30);

 if(!defensePlay.ground && config.flyOuts){
  defensePlay.out=true;defensePlay.safe=false;defensePlay.margin=Math.max(.05,(defensePlay.runnerEta-elapsed)/1000);
  defensePlay.reason=finite(info.ballY,0)>3.8?"HIGH FLY OUT":"FLY OUT";
  window.DBE_THROW_FIRST=false;
  try{dispatchEvent(new CustomEvent("dbe-defense-call",{detail:{kind:"fly",out:true,reason:defensePlay.reason,margin:defensePlay.margin}}))}catch{}
  return;
 }

 if(defensePlay.ground&&config.forceAtFirst){
  const throwEta=(240+distance*9.5)/(arm*skill);
  defensePlay.throwEta=throwEta;
  const arrival=elapsed+throwEta;
  const margin=(defensePlay.runnerEta-arrival)/1000;
  defensePlay.margin=margin;
  defensePlay.out=margin>0;
  defensePlay.safe=!defensePlay.out;
  defensePlay.reason=defensePlay.out?"FORCE OUT AT FIRST":"SAFE AT FIRST";
  window.DBE_THROW_FIRST=true;
  try{dispatchEvent(new CustomEvent("dbe-defense-call",{detail:{kind:"ground",out:defensePlay.out,safe:defensePlay.safe,reason:defensePlay.reason,margin}}))}catch{}
 }
};
window.DBE_SAFE_DEFENSE_RESULT=function(){
 if(!defensePlay.pending)return null;
 const result={out:!!defensePlay.out,safe:!!defensePlay.safe,reason:defensePlay.reason,margin:defensePlay.margin};
 resetDefensePlay();
 return result;
};

window.DBE_BAT_ELEVATION=function(power,error,win){
 if(!config.variableContact)return power>40?60:110;
 const n=Math.abs(clamp(Number(error)/Math.max(.001,Number(win)),-1,1));
 return n<.28?58+Math.random()*9:n<.62?70+Math.random()*16:103+Math.random()*18;
};

function applyGlobals(){
 config.speed=clamp(finite(config.speed,1),.6,1.6);
 config.hitWindow=clamp(finite(config.hitWindow,1),.65,1.5);
 config.intensity=clamp(finite(config.intensity,1),.70,1.28);
 config.frequency=clamp(finite(config.frequency,.9),0,1);
 config.outLimit=Math.round(clamp(finite(config.outLimit,5),3,999999));
 window.DBE_SPEED_MULT=paused?0:config.speed;
 window.DBE_HIT_WINDOW=config.hitWindow;
 window.DBE_NO_RAMP=!!config.noRamp;
 window.DBE_SCORE_MULT=clamp(finite(config.scoreMult,1),1,3);
 window.DBE_FORCE_HR=!!config.forceHR;
 window.DBE_OUT_LIMIT=config.outLimit;
 window.DBE_WALL_PHYSICS=!!config.wallPhysics;
 window.DBE_WALL_HEIGHT=clamp(finite(config.wallHeight,2.2),1.5,3.2);
 window.DBE_DEFENSE_ENABLED=!!config.defenseSystem;
}
applyGlobals();

/* Display scaling happens only AFTER the original game has picked a stable size. */
let display={logo:null,w:0,h:0,lastW:0,lastH:0,stable:0,ready:false};
function probeDisplay(){
 const logo=$("#hplogo");if(!logo)return;
 const r=logo.getBoundingClientRect();if(r.width<200||r.height<100)return;
 if(Math.abs(r.width-display.lastW)<1&&Math.abs(r.height-display.lastH)<1)display.stable++;else display.stable=0;
 display.lastW=r.width;display.lastH=r.height;
 if(!display.ready&&display.stable>=4){
  display={...display,logo,w:r.width,h:r.height,ready:true};
  logo.style.width=r.width+"px";logo.style.height=r.height+"px";logo.style.position="fixed";logo.style.left="50%";logo.style.top="50%";logo.style.margin="0";logo.style.transformOrigin="50% 50%";logo.style.zIndex="1";
  document.documentElement.style.overflow="hidden";document.body.style.overflow="hidden";
  applyDisplay();
 }
}
function applyDisplay(){
 if(!display.ready||!display.logo)return;
 const aw=Math.max(100,innerWidth-8),ah=Math.max(100,innerHeight-8);
 if(config.displayMode==="stretch"){
  display.logo.style.transform=`translate(-50%,-50%) scale(${aw/display.w},${ah/display.h})`;return;
 }
 let s=config.displayMode==="fill"?Math.max(aw/display.w,ah/display.h):config.displayMode==="native"?1:Math.min(aw/display.w,ah/display.h);
 s=clamp(s,.2,5);display.logo.style.transform=`translate(-50%,-50%) scale(${s})`;
}
function recalibrate(){
 if(display.logo){for(const k of["width","height","position","left","top","margin","transform"])display.logo.style[k]=""}
 display={logo:null,w:0,h:0,lastW:0,lastH:0,stable:0,ready:false};
}
const probe=setInterval(probeDisplay,180);setTimeout(()=>clearInterval(probe),8000);
addEventListener("resize",()=>setTimeout(applyDisplay,80));
addEventListener("fullscreenchange",()=>setTimeout(applyDisplay,180));

