const hud=document.createElement("div");hud.id="dbe-hud";
const toast=document.createElement("div");toast.id="dbe-toast";
const achToast=document.createElement("div");achToast.id="dbe-ach-toast";
const cue=document.createElement("div");cue.id="dbe-cue";
const colorbar=document.createElement("div");colorbar.id="dbe-colorbar";
const pauseBadge=document.createElement("div");pauseBadge.id="dbe-pause";pauseBadge.textContent="PAUSED";
const fx=document.createElement("div");fx.id="dbe-fx";
const boss=document.createElement("div");boss.id="dbe-boss";
const combo=document.createElement("div");combo.id="dbe-combo";
const perfectBurst=document.createElement("div");perfectBurst.id="dbe-perfect-burst";perfectBurst.textContent="PERFECT!";
const mission=document.createElement("div");mission.id="dbe-mission";
const playCall=document.createElement("div");playCall.id="dbe-call";
const afterimages=document.createElement("div");afterimages.id="dbe-afterimages";
const defenseGameOver=document.createElement("div");defenseGameOver.id="dbe-defense-gameover";
defenseGameOver.innerHTML=`<div><h2>GAME OVER</h2><p id="dbe-defense-gameover-text">The field got you.</p><button id="dbe-defense-restart">Restart game</button></div>`;
const debugOverlay=document.createElement("div");debugOverlay.id="dbe-debug-overlay";
document.body.append(fx,afterimages,openBtn,backdrop,panel,hud,toast,achToast,cue,colorbar,pauseBadge,boss,combo,perfectBurst,mission,playCall,defenseGameOver,debugOverlay);

let menuOpen=false,toastTimer=null,achTimer=null,cueTimer=null,libraryPage=0,bossTimer=null,fxTimer=null;
let audioCtx=null;
function audioReady(){
 try{if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==="suspended")audioCtx.resume()}catch{}
}
function tone(freq=440,dur=.07,type="sine",gain=.035,delay=0){
 if(!audioCtx)return;
 try{
  const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+delay;
  o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(gain,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  o.connect(g).connect(audioCtx.destination);o.start(t);o.stop(t+dur+.02);
 }catch{}
}
function sfx(kind){
 if(!audioCtx)return;
 if(kind==="perfect"){tone(660,.09,"triangle",.045);tone(990,.12,"triangle",.035,.07)}
 else if(kind==="legendary"){tone(180,.13,"sawtooth",.028);tone(360,.16,"triangle",.025,.07)}
 else if(kind==="achievement"){tone(523,.08,"triangle",.04);tone(659,.08,"triangle",.04,.09);tone(784,.15,"triangle",.04,.18)}
 else if(kind==="break"){tone(130,.09,"square",.02)}
}
function fxPitch(p){
 clearTimeout(fxTimer);fx.className="";if(!p)return;
 fx.style.setProperty("--fxc",variantColor(p,activeVariant||variantFor(1)));
 if(p.special==="black_hole")fx.className="dark";
 else if(p.special==="lightning"||p.special==="sonic")fx.className="lightning";
 else if(p.special==="glitch"||p.special==="quantum_zig")fx.className="glitch";
 else if(p.special==="dragon_breath"||p.special==="phoenix")fx.className="dragon";
 else if(p.id<=50||config.mode==="arcade")fx.className="glow";
 fxTimer=setTimeout(()=>fx.className="",900);
}
function showBoss(p,v){
 if(!p)return;clearTimeout(bossTimer);
 const isBoss=p.id<=50||config.mode==="legendary";
 if(!isBoss&&config.mode!=="arcade")return;
 const c=variantColor(p,v||variantFor(1));boss.style.setProperty("--bc",c);
 boss.innerHTML=`<div class="name">${p.icon||"⚾"} ${p.name} <span style="color:${c}">• ${(v||variantFor(1)).name}</span></div><div class="bossmeta">${p.desc} • ${p.category} • challenge #${challengeIndex(p.id,(v||variantFor(1)).id).toLocaleString()}</div>`;
 boss.classList.add("show");sfx("legendary");bossTimer=setTimeout(()=>boss.classList.remove("show"),1900);
}
function masteryFor(id){
 const m=totals.pitchMastery[id]||{seen:0,hits:0,hr:0,perfect:0};
 let medal="—";
 if(m.hr>=25&&m.perfect>=5)medal="💎 DIAMOND";
 else if(m.hr>=10)medal="🥇 GOLD";
 else if(m.hr>=3)medal="🥈 SILVER";
 else if(m.hr>=1)medal="🥉 BRONZE";
 return{...m,medal};
}
function updateMastery(id,key){
 if(!id)return;
 const m=totals.pitchMastery[id]||{seen:0,hits:0,hr:0,perfect:0};
 m[key]=(m[key]||0)+1;totals.pitchMastery[id]=m;
}
function perfectionRank(){
 const s=perfection.streak;
 return s>=50?"S+":s>=30?"S":s>=20?"A":s>=12?"B":s>=6?"C":s>=3?"D":"—";
}
function renderCombo(){
 const rank=perfectionRank(),pct=Math.min(100,perfection.streak*2);
 combo.style.display=config.mode==="perfectionism"?"block":"none";
 combo.innerHTML=`<div>PERFECTIONISM • Rank <b>${rank}</b></div><div>🔥 ${perfection.streak} streak • best ${perfection.best}</div><div class="combo-bar"><div style="width:${pct}%"></div></div>`;
}
function renderMissions(){
 const allDone=missions.every(m=>m.value>=m.target);
 mission.innerHTML=`<div class="title">${allDone?"RUN BOARD COMPLETE 🏆":"RUN CHALLENGES"}</div>`+
 missions.map(m=>`<div class="mission-line ${m.value>=m.target?"mission-done":""}">${m.value>=m.target?"✓":"○"} ${m.label} (${Math.min(m.value,m.target)}/${m.target})</div>`).join("");
 if(allDone&&!mission.__dbeCelebrated){mission.__dbeCelebrated=true;showToast("RUN BOARD COMPLETE!");sfx("achievement")}
}
function missionAdd(id,n=1){
 const m=missions.find(x=>x.id===id);if(!m)return;m.value+=n;renderMissions();
}
function resetMissions(){
 missions=missions.map(m=>({...m,value:0}));mission.__dbeCelebrated=false;renderMissions();
}
function showToast(text){toast.textContent=text;toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove("show"),1500)}
function showAchievement(a){achToast.textContent=`🏆 ${a.name} — ${a.desc}`;achToast.classList.add("show");clearTimeout(achTimer);achTimer=setTimeout(()=>achToast.classList.remove("show"),3000)}
function toggleMenu(force){
 menuOpen=typeof force==="boolean"?force:!menuOpen;
 panel.classList.toggle("open",menuOpen);backdrop.classList.toggle("open",menuOpen);
}
function showCue(p,v=activeVariant){
 if(!config.earlyCue||config.mode==="mystery")return;
 clearTimeout(cueTimer);
 if(!p){cue.classList.remove("show");colorbar.classList.remove("show");return}
 v=v||variantFor(1);
 const rule=window.DBE_CONTACT_RULE(),color=variantColor(p,v);
 cue.style.setProperty("--pc",color);colorbar.style.setProperty("--pc",color);
 cue.textContent=`#${p.id} • ${p.name} • ${v.tag} ${v.name} • ${p.special==="invisible"?"GHOST SEAM":rule.center<-.1?"EARLY":rule.center>.12?"WAIT":"CENTER"}`;
 cue.classList.add("show");colorbar.classList.add("show");
 cueTimer=setTimeout(()=>{cue.classList.remove("show");colorbar.classList.remove("show")},1850);
}

function unlock(id){
 if(achievementSet.has(id))return;
 const a=ACHIEVEMENTS.find(x=>x.id===id);if(!a)return;
 achievementSet.add(id);save();showAchievement(a);sfx("achievement");renderAchievements();
}
function checkAchievements(){
 if(totals.totalHits>=1)unlock("first_hit");
 if(totals.totalHR>=1)unlock("first_hr");
 if(totals.totalHR>=25)unlock("hr25");
 if(totals.totalHR>=100)unlock("hr100");
 if(totals.totalHR>=500)unlock("hr500");
 if(totals.longestHR>=300)unlock("long300");
 if(totals.longestHR>=400)unlock("long400");
 if(seen.size>=100)unlock("seen100");
 if(seen.size>=1500)unlock("seen1500");
 if(seen.size>=3000)unlock("seen3000");
 if(seenChallenges.size>=100)unlock("combo100");
 if(seenChallenges.size>=1500)unlock("combo1500");
 if(seenChallenges.size>=24000)unlock("combo24000");
 if(new Set([...seenChallenges].map(c=>challengeFor(c).variantId)).size>=VARIANT_COUNT)unlock("variants");
 if(mastered.size>=1)unlock("master1");
 if(mastered.size>=100)unlock("master100");
 if(mastered.size>=1000)unlock("master1000");
 if(mastered.size>=12000)unlock("master12000");
 if(mastered.size>=24000)unlock("master24000");
 if(mastered.size>=36000)unlock("master36000");
 if(mastered.size>=48000)unlock("master48000");
 const families=new Set([...seen].map(id=>profileFor(id).category));
 if(families.size>=new Set(PITCH_IDENTITIES.map(p=>p.category)).size)unlock("families");
 if(perfection.best>=5)unlock("perfect5");
 if(perfection.best>=10)unlock("perfect10");
 if(perfection.best>=25)unlock("perfect25");
 if(perfection.best>=50)unlock("perfect50");
 if(perfection.perfectHR>=10)unlock("perfecthr10");
 const masteryValues=Object.keys(totals.pitchMastery).map(id=>masteryFor(Number(id)));
 if(masteryValues.some(m=>m.medal.includes("DIAMOND")))unlock("diamond1");
 if([...seen].filter(id=>id>=1&&id<=50).length>=50)unlock("legend50");
}

