function applyMode(id){
 const m=MODES[id]||MODES.expanded;
 config.mode=id;config.pitchSystem=m.pitchSystem;
 for(const k of["outLimit","frequency","intensity","speed","noRamp"])if(m[k]!=null)config[k]=m[k];
 applyGlobals();save();syncUI();debugLog("mode.change",{mode:id,pitchSystem:config.pitchSystem});showToast(m.label);
}
function renderManual(){
 const p=profileFor(config.manualPitch),v=variantFor(config.manualVariant),rule={
  center:clamp(p.center+v.center,-.30,.34),window:clamp(p.window*v.window,.48,1.22)
 },color=variantColor(p,v);
 el.manual.value=p.id;el.manualVariant.value=v.id;
 el.manualPreview.innerHTML=`<span class="dbe-swatch" style="background:${color};color:${color}"></span><b>#${p.id} ${p.name} — ${v.name}</b><br><b>${p.desc}</b><br>${variantFeel(v.id)}<br>${p.signature}<br>Exact speed ${clamp(p.speed*v.speed,7,76).toFixed(1)} • center ${rule.center.toFixed(2)} • window ${rule.window.toFixed(2)} • challenge #${challengeIndex(p.id,v.id).toLocaleString()} / ${CHALLENGE_COUNT.toLocaleString()}`;
 if(el.variantStrip){
  el.variantStrip.innerHTML=VARIANTS.map(x=>{
   const c=variantColor(p,x);
   return `<button class="dbe-variant-chip ${x.id===v.id?"active":""}" style="--vc:${c}" data-variant-chip="${x.id}" title="${variantFeel(x.id)}">${x.tag}</button>`;
  }).join("");
  el.variantStrip.querySelectorAll("[data-variant-chip]").forEach(b=>b.onclick=()=>{
   config.manualVariant=Number(b.dataset.variantChip);save();renderManual();
  });
 }
}

function filteredProfiles(){
 const query=(el.libSearch.value||"").trim().toLowerCase(),fam=el.libFamily.value,motion=el.libMotion.value;
 const arr=[];
 for(let id=1;id<=PROFILE_COUNT;id++){
  const p=profileFor(id);
  if(fam!=="all"&&p.family.name!==fam)continue;
  if(motion!=="all"&&p.motion.name!==motion)continue;
  const hay=`${p.id} ${p.name} ${p.signature} ${p.desc} ${p.theme} ${p.form}`.toLowerCase();
  if(query&&!hay.includes(query))continue;
  arr.push(p);
 }
 return arr;
}
function renderLibrary(resetPage=false){
 if(resetPage)libraryPage=0;
 const all=filteredProfiles(),pageSize=40,maxPage=Math.max(0,Math.ceil(all.length/pageSize)-1);
 libraryPage=clamp(libraryPage,0,maxPage);
 const slice=all.slice(libraryPage*pageSize,(libraryPage+1)*pageSize),v=variantFor(Number(el.libVariant.value)||1);
 el.libPage.textContent=`${all.length.toLocaleString()} base pitches • variant: ${v.name} • page ${libraryPage+1}/${maxPage+1}`;
 el.libResults.innerHTML=slice.map(p=>{
  const color=variantColor(p,v),center=clamp(p.center+v.center,-.30,.34),window=clamp(p.window*v.window,.48,1.22);
  return `<button class="dbe-pitch-card" data-profile="${p.id}">
   <div class="dbe-pitch-name"><span class="dbe-swatch" style="background:${color};color:${color}"></span>#${p.id} ${p.name} — ${v.tag}</div>
   <div class="dbe-pitch-meta">${p.category} • ${p.theme} • ${p.style} • ${v.name}<br>${p.desc}<br>speed ${clamp(p.speed*v.speed,7,72).toFixed(1)} • center ${center.toFixed(2)} • window ${window.toFixed(2)}<br>challenge #${challengeIndex(p.id,v.id).toLocaleString()}</div>
  </button>`;
 }).join("")||`<div class="dbe-help">No pitches match.</div>`;
 el.libResults.querySelectorAll("[data-profile]").forEach(b=>b.addEventListener("click",()=>{
  config.manualPitch=Number(b.dataset.profile);config.manualVariant=v.id;config.mode="pitchlab";config.pitchSystem="manual";save();syncUI();showToast(`#${config.manualPitch} • ${v.name}`);
 }));
}

function renderGauntlet(){
 config.gauntletCurrent=Math.round(clamp(config.gauntletCurrent,1,CHALLENGE_COUNT));
 const c=challengeFor(config.gauntletCurrent),p=profileFor(c.profileId),v=variantFor(c.variantId),color=variantColor(p,v);
 const pct=((config.gauntletCurrent-1)/CHALLENGE_COUNT)*100;
 el.gauntletNum.textContent=`CHALLENGE ${config.gauntletCurrent.toLocaleString()} / ${CHALLENGE_COUNT.toLocaleString()}`;
 el.gauntletName.innerHTML=`<span class="dbe-swatch" style="background:${color};color:${color}"></span>Base #${p.id} ${p.name} — <b>${v.name}</b>`;
 el.gauntletBar.style.width=`${pct}%`;
 el.gauntletStats.textContent=`Mastered ${mastered.size.toLocaleString()}/${CHALLENGE_COUNT.toLocaleString()} exact combinations • base pitch ${p.id}/${PROFILE_COUNT} • variant ${v.id}/${VARIANT_COUNT} • repeats until HOME RUN`;
 el.gauntletJump.value=config.gauntletCurrent;
}
function renderPerfection(){
 if(!el.perfectRank)return;
 el.perfectRank.textContent=perfectionRank();
 el.perfectStats.textContent=`Perfect contacts ${perfection.perfects} • imperfect contacts ${perfection.imperfect} • perfect HR ${perfection.perfectHR} • live streak ${perfection.streak} • best ${perfection.best}`;
 el.perfectProgress.style.width=`${Math.min(100,perfection.streak*2)}%`;
 renderCombo();
 const ids=[activeProfileId,...Object.keys(totals.pitchMastery).map(Number)].filter(Boolean);
 const unique=[...new Set(ids)].slice(-8).reverse();
 el.masterGrid.innerHTML=unique.length?unique.map(id=>{
   const p=profileFor(id),m=masteryFor(id);
   return `<div class="dbe-medal"><b>#${id} ${p.name}</b><br>${m.medal}<br><span class="dbe-help">HR ${m.hr} • perfect ${m.perfect}</span></div>`;
 }).join(""):`<div class="dbe-help">Hit some named pitches to begin mastery.</div>`;
}
function showPlayCall(text,color="#ffffff"){
 playCall.style.setProperty("--cc",color);
 playCall.textContent=text;
 playCall.classList.remove("show");void playCall.offsetWidth;playCall.classList.add("show");
}
function spawnAfterimages(p){
 if(!p)return;
 const legendary=p.id<=50||["Portal","Ghost","Orbit","Spiral","Teleport","Glitch","Chaos"].some(k=>`${p.name} ${p.style}`.includes(k));
 if(!legendary)return;
 const color=variantColor(p,activeVariant||variantFor(1));
 for(let i=0;i<7;i++){
  const dot=document.createElement("i");dot.className="dbe-afterimage";
  dot.style.setProperty("--ac",color);
  dot.style.left=`${48+(i-3)*2.1}%`;dot.style.top=`${17+i*5.3}%`;
  const dx=(p.direction||1)*(12+i*5);dot.style.setProperty("--dx",`${dx}px`);dot.style.setProperty("--dy",`${58+i*8}px`);
  dot.style.animationDelay=`${i*.035}s`;afterimages.appendChild(dot);setTimeout(()=>dot.remove(),1100);
 }
}
function renderFoods(){
 if(!el.foodGrid)return;
 const configs=Array.isArray(window.DBE_CHARACTER_CONFIGS)?window.DBE_CHARACTER_CONFIGS:[];
 const all=[];
 if(configs.length){
  configs.forEach((cfg,i)=>{
   const f=cfg?.Da;
   if(!Array.isArray(f)||f.length<5)return;
   const width=Math.max(40,+f[3]||90),height=Math.max(70,+f[4]||140);
   const norm=clamp(((width*height)-12500)/9000,-1,1);
   const signature=`${f[0]||"sheet"}:${f[1]||0}:${f[2]||0}:${width}:${height}`;
   const label=norm>.58?"Slugger":norm>.28?"Power":norm<-.58?"Speedster":norm<-.28?"Quick":"Balanced";
   const power=1+clamp(norm*.10,-.10,.12),speed=1-clamp(norm*.10,-.10,.12);
   const seenData=discoveredFoods[signature];
   all.push({index:i+1,width,height,label,power,speed,seen:seenData?.seen||0,signature});
  });
 }else{
  Object.values(discoveredFoods).forEach((f,i)=>all.push({index:i+1,...f}));
 }
 el.foodGrid.innerHTML=all.length?all.map(f=>`<div class="dbe-food-card"><b>Food Type ${f.index} • ${f.label}</b><div class="mini">${f.width}×${f.height} sprite • power ${Number(f.power).toFixed(2)}× • run ${Number(f.speed).toFixed(2)}× • ${f.seen?`seen ${f.seen}×`:"not encountered yet"}</div></div>`).join(""):`<div class="dbe-help">Character configs will appear as soon as the original game initializes its lineup.</div>`;
}
function renderBossLadder(){
 if(!el.bossLadderName)return;
 bossLadder.current=Math.round(clamp(bossLadder.current,1,50));
 const p=profileFor(bossLadder.current),v=variantFor(1+((p.id*7-1)%VARIANT_COUNT));
 el.bossLadderName.innerHTML=`${p.icon||"⚾"} BOSS ${p.id}/50 — ${p.name}`;
 el.bossLadderDesc.textContent=`${p.desc} • fixed boss variant: ${v.name}`;
 el.bossProgress.style.width=`${Math.max(0,(bossLadder.current-1)/50*100)}%`;
 el.bossLadderStats.textContent=`Defeated ${new Set(bossLadder.defeated).size}/50 • next boss #${bossLadder.current}`;
}
