function debugSnapshot(){
 return {
  version:VERSION,build:BUILD_NAME,time:new Date().toISOString(),fps:debugFps,
  mode:config.mode,pitchSystem:config.pitchSystem,activeProfileId,activePitch:activeProfile?.name||null,activeVariant:activeVariant?.name||null,activeChallengeId,
  gameReady:!!window.DBE_GAME,fielders:Array.isArray(window.DBE_FIELDERS)?window.DBE_FIELDERS.length:0,characterConfigs:Array.isArray(window.DBE_CHARACTER_CONFIGS)?window.DBE_CHARACTER_CONFIGS.length:0,
  outLimit:config.outLimit,defense:!!config.defenseSystem,fouls:!!config.foulRules,wall:!!config.wallPhysics,display:config.displayMode,
  session:debugSafe(session),perfection:debugSafe(perfection),defensePlay:debugSafe(defensePlay),foulState:debugSafe(foulState),events:debugEvents.length,
  browser:{userAgent:navigator.userAgent,language:navigator.language,viewport:`${innerWidth}x${innerHeight}`,devicePixelRatio:window.devicePixelRatio||1},
  buildReport:debugBuildReport
 };
}
function debugSelfCheck(){
 const checks=[
  ["game instance",!!window.DBE_GAME],["3,000 pitch identities",PITCH_IDENTITIES.length===3000],["unique pitch names",new Set(PITCH_IDENTITIES.map(p=>p.name)).size===3000],["16 variants",VARIANTS.length===16],
  ["pitch profile finite",Number.isFinite(profileFor(1).speed)&&Number.isFinite(profileFor(3000).speed)],["display scaler ready",!!display.ready],["fielder bridge",Array.isArray(window.DBE_FIELDERS)],["character config bridge",Array.isArray(window.DBE_CHARACTER_CONFIGS)]
 ];
 const pass=checks.filter(x=>x[1]).length;debugLog("self-check",{pass,total:checks.length,checks:Object.fromEntries(checks)});return {pass,total:checks.length,checks};
}
function debugIssueText(){
 const s=debugSnapshot(),check=debugSelfCheck();
 return `## DBE V19 Debug Report\n\n**Version:** ${VERSION} — ${BUILD_NAME}\n**Time:** ${s.time}\n**Mode:** ${s.mode} / ${s.pitchSystem}\n**Pitch:** #${s.activeProfileId||0} ${s.activePitch||"none"} / ${s.activeVariant||"none"}\n**FPS:** ${s.fps}\n**Self-check:** ${check.pass}/${check.total}\n**Game ready:** ${s.gameReady}\n**Fielders:** ${s.fielders}\n**Character configs:** ${s.characterConfigs}\n**Display:** ${s.display} @ ${s.browser.viewport}\n**Defense/Fouls/Wall:** ${s.defense} / ${s.fouls} / ${s.wall}\n\n### Recent events\n\n\`\`\`json\n${JSON.stringify(debugEvents.slice(-40),null,2)}\n\`\`\`\n`;
}
function exportDebugJson(){
 const payload={snapshot:debugSnapshot(),selfCheck:debugSelfCheck(),events:debugEvents};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");
 a.href=url;a.download=`dbe-v19-debug-${new Date().toISOString().replace(/[:.]/g,"-")}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),800);
}
function renderDebug(force=true){
 if(el.debugStatus){
  const s=debugSnapshot(),check=force?debugSelfCheck():null;
  el.debugStatus.innerHTML=`<div>FPS<b>${s.fps}</b></div><div>GAME<b class="${s.gameReady?"dbe-debug-ok":"dbe-debug-warn"}">${s.gameReady?"READY":"WAIT"}</b></div><div>FIELDERS<b>${s.fielders}</b></div><div>EVENTS<b>${s.events}</b></div><div>PITCH<b>#${s.activeProfileId||0}</b></div><div>VARIANT<b>${s.activeVariant||"—"}</b></div><div>DEFENSE<b>${s.defense?"ON":"OFF"}</b></div><div>SELF-CHECK<b>${check?`${check.pass}/${check.total}`:"—"}</b></div>`;
 }
 if(el.debugLog)el.debugLog.textContent=debugEvents.slice(-100).reverse().map(e=>`${e.at.slice(11,23)}  ${e.type}  ${JSON.stringify(e.data)}`).join("\n")||"No debug events yet.";
 if(debugOverlayEnabled){const s=debugSnapshot();debugOverlay.textContent=`DBE ${VERSION} DEBUG • F9\nFPS ${s.fps} • ${s.mode}\nPitch #${s.activeProfileId||0} ${s.activePitch||"—"}\nVariant ${s.activeVariant||"—"}\nChallenge ${s.activeChallengeId||0}/${CHALLENGE_COUNT}\nGame ${s.gameReady?"READY":"WAIT"} • fielders ${s.fielders}\nDefense ${s.defense?"ON":"OFF"} • fouls ${s.fouls?"ON":"OFF"} • wall ${s.wall?"ON":"OFF"}\nEvents ${s.events}`}
}
