function updateHud(){
 hud.style.display=config.hud?"block":"none";
 const p=activeProfile,v=activeVariant,m=p?masteryFor(p.id):null;
 const identity=config.mode==="mystery"&&p?"??? MYSTERY PITCH ???":p?`#${p.id} ${p.name} • ${v?.name||"Standard"}`:"Vanilla pitch";
 const perfectLine=config.mode==="perfectionism"?`<br>PERFECT streak ${perfection.streak} • Rank ${perfectionRank()} • best ${perfection.best}`:"";
 const medalLine=m&&m.medal!=="—"?`<br>${m.medal}`:"";
 const foulLine=config.foulRules?`<br>Foul strikes ${foulState.strikes}/2`:"";
 const bossLine=config.pitchSystem==="bossladder"?`<br>Boss ${bossLadder.current}/50 • defeated ${new Set(bossLadder.defeated).size}`:"";
 hud.innerHTML=`<b>${MODES[config.mode]?.label||"Expanded"}</b> • Runs ${session.score} • Hits ${session.hits} • HR ${session.hr}<br>${identity}${perfectLine}${medalLine}${foulLine}${bossLine}${config.pitchSystem==="gauntlet"?`<br>Challenge ${config.gauntletCurrent.toLocaleString()}/${CHALLENGE_COUNT.toLocaleString()} • mastered ${mastered.size.toLocaleString()}`:""}`;
}
function syncUI(){
 el.mode.value=config.mode;el.modeHelp.textContent=MODES[config.mode]?.desc||"";
 el.frequency.value=config.frequency;el.frequencyV.textContent=Math.round(config.frequency*100)+"%";
 el.intensity.value=config.intensity;el.intensityV.textContent=Number(config.intensity).toFixed(2)+"×";
 el.randomVariants.checked=!!config.randomVariants;
 el.outs.value=config.outLimit;el.display.value=config.displayMode;
 el.hitWindow.value=config.hitWindow;el.hitWindowV.textContent=Number(config.hitWindow).toFixed(2)+"×";
 el.speed.value=config.speed;el.speedV.textContent=Number(config.speed).toFixed(2)+"×";
 el.variable.checked=!!config.variableContact;el.traits.checked=!!config.playerTraits;el.ramp.checked=!config.noRamp;
 el.hats.checked=!!config.hatColors;el.cueToggle.checked=!!config.earlyCue;el.hudToggle.checked=!!config.hud;
 el.wall.checked=!!config.wallPhysics;el.wallHeight.value=config.wallHeight;el.wallHeightV.textContent=Number(config.wallHeight).toFixed(1);
 if(el.traitStatus)el.traitStatus.textContent=`Current food trait: ${lastTrait.label} • power ${lastTrait.power.toFixed(2)}× • run speed ${lastTrait.speed.toFixed(2)}×`;
 el.manualVariant.value=config.manualVariant;if(el.libVariant)el.libVariant.value=config.manualVariant;el.pause.textContent=paused?"Resume":"Pause";
 el.defense.checked=!!config.defenseSystem;el.flyOuts.checked=!!config.flyOuts;el.forceFirst.checked=!!config.forceAtFirst;el.fouls.checked=!!config.foulRules;el.defenseSkill.value=config.defenseDifficulty;el.defenseSkillV.textContent=Number(config.defenseDifficulty).toFixed(2)+"×";
 renderManual();renderGauntlet();renderPerfection();renderFoods();renderBossLadder();renderAchievements();renderSession();updateHud();
}

function commit(){applyGlobals();save();syncUI()}

